import{c as a,Q as t,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Understanding the Challenges in Iterative Generative Optimization with LLMs","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.23994","title":"Understanding the Challenges in Iterative Generative Optimization with LLMs","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.23994,"authors":["Allen Nie","Xavier Daull","Zhiyi Kuang","Abhinav Akkiraju","Anish Chaudhuri","Max Piasevoli","Ryan Rong","YuCheng Yuan","Prerit Choudhary","Shannon Xiao","Rasool Fakoor","Adith Swaminathan","Ching-An Cheng"],"domains":["cs.LG"],"html":"https://arxiv.org/html/2603.23994v1","pdf_path":"pdfs/2603.23994.pdf","published_date":"2026-03-25T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-25-challenges-iterative-generative-optimization-2603-23994.md","filePath":"research/papers/2026-03-25-challenges-iterative-generative-optimization-2603-23994.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-03-25-challenges-iterative-generative-optimization-2603-23994.md"};function o(s,e,l,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="understanding-the-challenges-in-iterative-generative-optimization-with-llms" tabindex="-1">Understanding the Challenges in Iterative Generative Optimization with LLMs <a class="header-anchor" href="#understanding-the-challenges-in-iterative-generative-optimization-with-llms" aria-label="Permalink to &quot;Understanding the Challenges in Iterative Generative Optimization with LLMs&quot;">​</a></h1><p><strong>Authors</strong>: Allen Nie, Xavier Daull, Zhiyi Kuang, Abhinav Akkiraju, Anish Chaudhuri, Max Piasevoli, Ryan Rong, YuCheng Yuan, Prerit Choudhary, Shannon Xiao, Rasool Fakoor, Adith Swaminathan, Ching-An Cheng <strong>Published</strong>: March 25, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.23994" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.23994</a> · <a href="https://arxiv.org/html/2603.23994v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.23994 <strong>Categories</strong>: cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.23994" target="_blank" rel="noreferrer">research/papers/pdfs/2603.23994.pdf</a> (39 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Generative optimization uses large language models (LLMs) to iteratively improve artifacts (such as code, workflows or prompts) using execution feedback. It is a promising approach to building self-improving agents, yet in practice remains brittle: despite active research, only 9% of surveyed agents used any automated optimization. We argue that this brittleness arises because, to set up a learning loop, an engineer must make &#39;hidden&#39; design choices: What can the optimizer edit and what is the &#39;right&#39; learning evidence to provide at each update? We investigate three factors that affect most applications: the starting artifact, the credit horizon for execution traces, and batching trials and errors into learning evidence. Through case studies in MLAgentBench, Atari, and BigBench Extra Hard, we find that these design decisions can determine whether generative optimization succeeds, yet they are rarely made explicit in prior work. Different starting artifacts determine which solutions are reachable in MLAgentBench, truncated traces can still improve Atari agents, and larger minibatches do not monotonically improve generalization on BBEH. We conclude that the lack of a simple, universal way to set up learning loops across domains is a major hurdle for productionization and adoption. We provide practical guidance for making these choices.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>將 generative optimization（用 LLM 以 execution feedback 迭代改進 code / workflow / prompt 等 artifact）的脆弱性，歸因於三個常被隱藏（hidden）的工程設計選擇，並將其顯式化。</li><li>定義並系統性研究三個跨應用的關鍵因子：(1) <strong>starting artifact</strong>（起始 artifact）；(2) <strong>credit horizon for execution traces</strong>（execution trace 的歸因視窗 / 截斷長度）；(3) <strong>batching trials and errors into learning evidence</strong>（將試誤批次化為 learning evidence，即 minibatch 大小）。</li><li>透過 MLAgentBench、Atari、BigBench Extra Hard (BBEH) 三個 case study 提供跨域實證，顯示這些選擇決定 learning loop 成敗。</li><li>提出實務指引（practical guidance），協助工程師做出這些隱藏選擇，並指出缺乏「跨域通用 learning loop 建置法」是 productionization 與採用的主要障礙。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>調查的 agents 中<strong>僅 9%</strong> 使用任何 automated optimization——量化佐證該技術實務脆弱、採用率低。</li><li><strong>MLAgentBench</strong>：不同 starting artifact 決定哪些 solution 為 reachable（起點限縮可達解空間）。</li><li><strong>Atari</strong>：即使 execution trace 被截斷（truncated traces），仍可改進 agent——credit horizon 不必完整。</li><li><strong>BBEH</strong>：較大 minibatch <strong>並非單調（non-monotonic）</strong> 改善 generalization——批次越大未必越好。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（依 abstract 推斷）。判斷弱點：</p><ul><li>結論建立於三個特定 benchmark（MLAgentBench / Atari / BBEH），對其他 artifact 型態（如真實生產 codebase、長程 agentic workflow）的外推性未經驗證。</li><li>提出的是「practical guidance」而非可自動化的通用演算法——abstract 自承「lack of a simple, universal way」，即未解決根本問題，仍依賴人工判斷三個隱藏選擇。</li><li>「9% 採用率」來自 surveyed agents，調查範圍 / 取樣偏差未在 abstract 交代。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>The Loop 迭代紀律對應</strong>：本論文的三隱藏選擇（starting artifact / credit horizon / minibatch）正對應 The Loop 中 IDENTIFY 階段「顯露假設」的盲點——learning loop 的成功條件常被隱式選定。可作為「成功條件須機械可驗證、選擇須顯式」的外部佐證。⚠️ 落地門檻：論文層級為 benchmark 實證，非直接可套用的 harness 規則。</li><li><strong><code>unverified_success</code> 閘門呼應</strong>：BBEH「larger minibatch 非單調改善」與「truncated trace 仍可改進」說明——更多 evidence / 更長 trace ≠ 更好結果，呼應 workspace「context 非越多越好（NLAH）」與「subagent verdict 非證據、需機械重驗」紀律。⚠️ 兩者僅概念類比，無共用度量。</li><li><strong>autoresearch / autoload-evolution 參考</strong>：論文的 modify→execution feedback→update 迴圈與 autoresearch 的 <code>modify → verify → keep/discard</code>、autoload-evolution 的閉環同構；其「credit horizon」與「batching evidence」可作為這兩個自我演化 skill 設計 evidence 注入策略時的 prior。⚠️ 需先驗證 benchmark 結論在 skill 實際 eval 集上是否重現，不可直接移植參數。</li><li><strong>誠實標記</strong>：以上均為概念對映，論文未針對任何 workspace 檔案或 skill；落地需獨立實驗背書。</li></ul>',17)])])}const p=a(n,[["render",o]]);export{u as __pageData,p as default};
